import React, { cloneElement, Ref } from 'react';
import { StyledProgressTracker } from './ProgressTracker.styles';
import { ProgressTrackerProps } from './ProgressTracker.types';
import ProgressTrackerContext from './ProgressTrackerContext';

const ProgressTracker = React.forwardRef(
  (
    { currentStep = 0, children, orientation = 'horizontal', size = 'large' }: ProgressTrackerProps,
    forwardedRef: Ref<HTMLDivElement>
  ): JSX.Element => {
    const steps = React.Children.map(
      children as React.ReactElement[],
      (child: React.ReactElement, index: number) =>
        cloneElement(child, {
          index,
          ...child.props,
        })
    );

    const contextValue = React.useMemo(
      () => ({ currentStep, orientation, size }),
      [currentStep, orientation, size]
    );

    return (
      <ProgressTrackerContext.Provider value={contextValue}>
        <StyledProgressTracker ref={forwardedRef} data-testid="progress-tracker-container">
          {steps}
        </StyledProgressTracker>
      </ProgressTrackerContext.Provider>
    );
  }
);

export default ProgressTracker;
